import userEvent from "@testing-library/user-event";
import App from "./App.jsx";

function jsonResponse(body, status = 200) {
  return {
    ok: status >= 200 && status < 300,
    status,
    json: async () => body,
  };
}

function mockApi(initial = []) {
  const store = initial.map((todo) => ({ ...todo }));
  let seq = store.length;

  global.fetch = vi.fn(async (url, options = {}) => {
    const path = String(url);
    const method = (options.method || "GET").toUpperCase();

    if (path === "/api/todos" && method === "GET") {
      return jsonResponse(store);
    }
    if (path === "/api/todos" && method === "POST") {
      const body = JSON.parse(options.body);
      seq += 1;
      const todo = { id: `id-${seq}`, title: body.title, done: false };
      store.unshift(todo);
      return jsonResponse(todo, 201);
    }
    const match = path.match(/^\/api\/todos\/([^/]+)$/);
    if (match && method === "PATCH") {
      const todo = store.find((item) => item.id === match[1]);
      if (!todo) return jsonResponse({ error: "todo not found" }, 404);
      Object.assign(todo, JSON.parse(options.body));
      return jsonResponse(todo);
    }
    if (match && method === "DELETE") {
      const index = store.findIndex((item) => item.id === match[1]);
      if (index === -1) return jsonResponse({ error: "todo not found" }, 404);
      store.splice(index, 1);
      return { ok: true, status: 204, json: async () => ({}) };
    }
    return jsonResponse({ error: "not found" }, 404);
  });
}

